from pydantic.dataclasses import dataclass

@dataclass
class BaseVendorConfig:
    config_id: int
    provider_name: str

@dataclass
class VendorConfigDetail(BaseVendorConfig):
    api_endpoint: str
    webhook_signing_secret: str
    client_certificate_pem: str

@router.get("/integrations/vendor-configs/{config_id}", response_model=VendorConfigDetail)
async def get_vendor_config(
    config_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    config = db.query(VendorConfig).filter(
        VendorConfig.id == config_id,
        VendorConfig.organization_id == current_user.organization_id
    ).first()
    if not config:
        raise HTTPException(status_code=404, detail="Vendor configuration not found or access denied")
    return config
